from __future__ import annotations  # Enable postponed annotations for a compact plotting script.
from pathlib import Path  # Resolve the result directory and output image path portably.
import pandas as pd  # Read the machine-readable adaptive history generated by the numerical experiment.
import matplotlib.pyplot as plt  # Draw the requested linear-axis scatter and trajectory plot.

ROOT = Path(__file__).resolve().parent  # Anchor plotting input and output to the experiment directory.
RESULTS_DIR = ROOT / "results"  # Read numerical results and write the final figure in the same compact artifact directory.
HISTORY_PATH = RESULTS_DIR / "history.csv"  # Locate the adaptive-history table produced by run.py.
OUTPUT_PATH = RESULTS_DIR / "error_dof_linear.png"  # Define the requested script-generated linear-coordinate figure path.

df = pd.read_csv(HISTORY_PATH)  # Load all solved adaptive states from the completed numerical experiment.
global_df = df[df["method"] == "global_dorfler"].sort_values("dof").copy()  # Extract and resource-order the conventional global Dörfler trajectory.
semantic_df = df[df["method"] == "semantic_partition_dorfler"].sort_values("dof").copy()  # Extract and resource-order the independently normalized semantic trajectory.

fig, ax = plt.subplots(figsize=(10.5, 6.2))  # Create one uncluttered figure using ordinary linear coordinates on both axes.
ax.plot(global_df["dof"], 100.0 * global_df["qoi_rel_error"], marker="o", linewidth=1.8, label="Global Dörfler")  # Plot all actual global Dörfler solver states as connected scatter points.
ax.plot(semantic_df["dof"], 100.0 * semantic_df["qoi_rel_error"], marker="s", linewidth=1.8, label="Semantic domains + local Dörfler")  # Plot all actual semantic-normalization solver states as connected scatter points.
ax.set_xlabel("DOF (resource)")  # Label the horizontal axis with the finite-element resource proxy.
ax.set_ylabel("QoI relative error (%)")  # Label the vertical axis with true reference-relative QoI error in percent.
ax.set_title("Independent semantic normalization domains vs global Dörfler")  # Give the figure a concise algorithm-specific title.
ax.grid(True, alpha=0.25)  # Add a light Cartesian grid without transforming either axis logarithmically.
ax.legend()  # Show which trajectory corresponds to each adaptive marking strategy.

for _, row in global_df.iterrows():  # Traverse every actual global Dörfler solver state for round labels.
    ax.annotate(f"r{int(row['round'])}", (row["dof"], 100.0 * row["qoi_rel_error"]), xytext=(5, 5), textcoords="offset points", fontsize=8)  # Label each global scatter point with its adaptive round index.
for _, row in semantic_df.iterrows():  # Traverse every actual semantic-normalization solver state for round labels.
    ax.annotate(f"r{int(row['round'])}", (row["dof"], 100.0 * row["qoi_rel_error"]), xytext=(5, -12), textcoords="offset points", fontsize=8)  # Label each semantic scatter point with its adaptive round index.

fig.tight_layout()  # Adjust plot margins so labels and legend remain fully visible in the saved image.
fig.savefig(OUTPUT_PATH, dpi=220, bbox_inches="tight")  # Save the requested high-resolution linear-axis PNG into the GitHub Actions artifact directory.
plt.close(fig)  # Close the figure explicitly so the headless Actions runner releases plotting resources cleanly.
print(f"[plot] wrote {OUTPUT_PATH}")  # Record the exact generated figure path in the GitHub Actions log.
